// Build every HubSpot request body for this lead (CRM v3 objects API).
//   contact  – upserted by email: an existing contact is updated, never duplicated
//   company  – found by domain (or by name when there is no company domain), else created
//   note     – research summary, sources, score reasons and the email / outcome
//   task     – follow-up in FOLLOW_UP_DAYS after a sent email; due now after a timeout
const { lead, enrichment, scoring, decision, email, outcome } = $input.first().json;
const now = Date.now();
const days = Number($env.FOLLOW_UP_DAYS || 3);
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const nameParts = String(lead.name || '').trim().split(/\s+/);

const reasons = scoring.criteria
  .map((c) => `${c.name}: ${c.rating}/3 (${c.points} of ${c.weight}) – ${c.reason}`).join('\n');
const contact = {
  email: lead.email,
  firstname: nameParts[0] || '',
  lastname: nameParts.slice(1).join(' '),
  jobtitle: lead.role || '',
  company: lead.company || '',
  ...(lead.website_domain ? { website: lead.website_domain } : {}),
  ai_lead_score: String(scoring.score),
  ai_lead_tier: scoring.tier,
  ai_score_reasons: `${scoring.score}/100 (${scoring.tier})\n${reasons}`,
  ai_last_processed: String(now),
};

const companySearch = lead.website_domain
  ? { propertyName: 'domain', value: lead.website_domain }
  : lead.company ? { propertyName: 'name', value: lead.company } : null;
const company = companySearch ? {
  search: { filterGroups: [{ filters: [{ ...companySearch, operator: 'EQ' }] }],
    properties: ['name', 'domain'], limit: 1 },
  create: { properties: { name: lead.company || lead.website_domain,
    ...(lead.website_domain ? { domain: lead.website_domain } : {}) } },
} : null;

const profile = enrichment.profile || {};
const facts = [['What they do', profile.what_they_do], ['Industry', profile.industry],
  ['Size', profile.size_estimate], ['Location', profile.location]]
  .filter(([, f]) => f && f.value !== 'Unknown').map(([label, f]) => `${label}: ${f.value} (${f.confidence})`)
  .concat((profile.notable_facts || []).map((f) => `${f.fact} (${f.confidence})`));
const outcomeText = {
  approved: `Email sent, approved by ${decision?.approver}.`,
  approved_edited: `Email sent with edits by ${decision?.approver}.`,
  rejected: `Reply rejected by ${decision?.approver}: ${decision?.reject_reason}. No email sent.`,
  timeout: 'No decision within the approval window. No email sent; manual follow-up needed.',
  cold: 'Cold lead: no email drafted.',
}[outcome];
const noteBody = [
  `<p><strong>LeadPilot: ${scoring.score}/100 ${esc(scoring.tier.toUpperCase())}</strong> – ${esc(outcomeText)}</p>`,
  `<p><strong>Score reasons</strong><br>${esc(reasons).replace(/\n/g, '<br>')}</p>`,
  `<p><strong>Research</strong> (${esc(enrichment.enrichment_status)}${enrichment.enrichment_note ? `: ${esc(enrichment.enrichment_note)}` : ''})<br>`
    + `${facts.map(esc).join('<br>') || 'Nothing found'}</p>`,
  `<p><strong>Sources</strong><br>${(enrichment.sources || []).map((s) => `<a href="${esc(s.url)}">${esc(s.url)}</a>`).join('<br>') || 'none'}</p>`,
  `<p><strong>Their message</strong><br>${esc(lead.message).replace(/\n/g, '<br>')}</p>`,
  email ? `<p><strong>Email sent to ${esc(email.to)}</strong>${email.redirected_from ? ` (demo redirect for ${esc(email.redirected_from)})` : ''}<br>`
    + `Subject: ${esc(email.subject)}<br>${esc(email.body).replace(/\n/g, '<br>')}</p>` : '',
].join('');

const taskFor = {
  approved: { subject: `Follow up with ${lead.name} (${lead.company || lead.website_domain})`, due: now + days * 86400000, priority: scoring.tier === 'hot' ? 'HIGH' : 'MEDIUM' },
  approved_edited: { subject: `Follow up with ${lead.name} (${lead.company || lead.website_domain})`, due: now + days * 86400000, priority: scoring.tier === 'hot' ? 'HIGH' : 'MEDIUM' },
  timeout: { subject: `Manual follow-up: ${lead.name} (${lead.company || lead.website_domain}) – approval timed out`, due: now, priority: 'HIGH' },
}[outcome];
const task = taskFor ? { properties: {
  hs_timestamp: String(taskFor.due),
  hs_task_subject: taskFor.subject.slice(0, 250),
  hs_task_body: `${outcomeText} Score ${scoring.score}/100 (${scoring.tier}). Lead ${lead.lead_id}.`,
  hs_task_status: 'NOT_STARTED',
  hs_task_priority: taskFor.priority,
  hs_task_type: 'EMAIL',
} } : null;

return [{ json: {
  lead_id: lead.lead_id,
  outcome,
  contact: { inputs: [{ idProperty: 'email', id: lead.email, properties: contact }] },
  company,
  note: { properties: { hs_timestamp: String(now), hs_note_body: noteBody } },
  task,
} }];

// DRY_RUN: record the HubSpot requests instead of sending them.
const plan = $('Build CRM payloads').first().json;
const dry_actions = [
  { type: 'hubspot.contacts.upsert', body: plan.contact },
  plan.company && { type: 'hubspot.companies.find_or_create', body: plan.company },
  { type: 'hubspot.notes.create', body: plan.note },
  plan.task && { type: 'hubspot.tasks.create', body: plan.task },
].filter(Boolean);
return [{ json: { dry_actions } }];

// Link the note and task to the contact (and company, when there is one).
const plan = $('Build CRM payloads').first().json;
const upsert = $('Upsert contact').first().json;
if (!upsert.results || !upsert.results.length) {
  throw new Error(`HubSpot contact upsert returned no record: ${JSON.stringify(upsert.errors || upsert).slice(0, 300)}`);
}
const contactId = upsert.results[0].id;
let companyId = null;
if ($('Create company').isExecuted) companyId = $('Create company').first().json.id;
else if ($('Find company').isExecuted && $('Find company').first().json.total > 0) {
  companyId = $('Find company').first().json.results[0].id;
}
const link = (id, typeId) => ({ to: { id }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: typeId }] });
return [{ json: {
  note: { ...plan.note, associations: [link(contactId, 202), ...(companyId ? [link(companyId, 190)] : [])] },
  task: plan.task ? { ...plan.task, associations: [link(contactId, 204), ...(companyId ? [link(companyId, 192)] : [])] } : null,
} }];

// Collect the HubSpot record IDs (or, with DRY_RUN, the requests that were skipped).
const plan = $('Build CRM payloads').first().json;
const seen = (name) => $(name).isExecuted;
if (seen('Dry-run CRM')) {
  return [{ json: { dry_run: true, outcome: plan.outcome,
    dry_actions: $('Dry-run CRM').first().json.dry_actions } }];
}
const contact = $('Upsert contact').first().json.results[0];
let companyId = null;
if (seen('Create company')) companyId = $('Create company').first().json.id;
else if (seen('Find company') && $('Find company').first().json.total > 0) {
  companyId = $('Find company').first().json.results[0].id;
}
return [{ json: {
  dry_run: false,
  outcome: plan.outcome,
  contact_id: contact.id,
  contact_created: Boolean(contact.new),
  company_id: companyId,
  company_created: seen('Create company'),
  note_id: $('Create note').first().json.id,
  task_id: seen('Create task') ? $('Create task').first().json.id : null,
} }];
